#!/usr/bin/env bash # Comprehensive platform detection
# Detect the operating system detect_os() { case "$(uname -s)" in Linux*) echo "linux" ;; Darwin*) echo "macos" ;; MINGW*|MSYS*|CYGWIN*) echo "windows" ;; *) echo "unknown" ;; esac }
# Detect the environment (container, WSL, native, etc.) detect_environment() { local os os=$(detect_os)
if [[ "$os" == "linux" ]]; then if [[ -f /.dockerenv ]] || [[ -f /run/.containerenv ]]; then echo "container" elif grep -qi microsoft /proc/version 2>/dev/null; then if [[ -n "${WSL_DISTRO_NAME:-}" ]]; then echo "wsl2" else echo "wsl1" fi elif [[ -n "${REMOTE_CONTAINERS:-}" ]] || [[ -n "${CODESPACES:-}" ]]; then echo "devcontainer" else echo "native" fi elif [[ "$os" == "macos" ]]; then if [[ $(sysctl -n machdep.cpu.brand_string 2>/dev/null) == *"Apple"* ]]; then echo "apple-silicon" else echo "intel" fi elif [[ "$os" == "windows" ]]; then echo "gitbash" else echo "unknown" fi }
# Detect architecture detect_arch() { case "$(uname -m)" in x86_64|amd64) echo "amd64" ;; aarch64|arm64) echo "arm64" ;; armv7l) echo "armv7" ;; *) echo "unknown" ;; esac }
# Get package manager detect_package_manager() { if command -v brew &>/dev/null; then echo "brew" elif command -v apt-get &>/dev/null; then echo "apt" elif command -v dnf &>/dev/null; then echo "dnf" elif command -v yum &>/dev/null; then echo "yum" elif command -v pacman &>/dev/null; then echo "pacman" elif command -v apk &>/dev/null; then echo "apk" else echo "unknown" fi }

# Terminal color support detection and logging functions

# Initialize colors if terminal supports them
setup_colors() {
    if [[ -t 1 ]] && [[ "${TERM:-dumb}" != "dumb" ]]; then
        RED='\033[0;31m'
        GREEN='\033[0;32m'
        YELLOW='\033[1;33m'
        BLUE='\033[0;34m'
        PURPLE='\033[0;35m'
        CYAN='\033[0;36m'
        NC='\033[0m'  # No Color
    else
        RED=''
        GREEN=''
        YELLOW=''
        BLUE=''
        PURPLE=''
        CYAN=''
        NC=''
    fi
}

log_info() {
    echo -e "${BLUE}ℹ${NC}  $*"
}

log_success() {
    echo -e "${GREEN}✓${NC}  $*"
}

log_warning() {
    echo -e "${YELLOW}⚠${NC}  $*" >&2
}

log_error() {
    echo -e "${RED}✗${NC}  $*" >&2
}

log_step() {
    echo -e "${PURPLE}→${NC}  $*"
}

log_debug() {
    if [[ "${DEBUG:-0}" == "1" ]]; then
        echo -e "${CYAN}[DEBUG]${NC} $*" >&2
    fi
}

# Initialize colors on source
setup_colors

# Editor shim - uses first available editor edit() { local file="${1:-}" local editors=("$EDITOR" "$VISUAL" "code" "nvim" "vim" "vi" "nano")
for editor in "${editors[@]}"; do if [[ -n "$editor" ]] && command -v "$editor" &>/dev/null; then "$editor" "$file" return $? fi done
log_error "No editor found" return 1 }
# Open URL/file shim - cross-platform open_url() { local url="${1:?URL required}"
case "$(detect_os)" in macos) open "$url" ;; linux) if [[ -n "${WSL_DISTRO_NAME:-}" ]]; then # WSL: use Windows browser cmd.exe /c start "$url" 2>/dev/null || xdg-open "$url" else xdg-open "$url" fi ;; windows) start "$url" ;; *) log_error "Cannot open URL on this platform" return 1 ;; esac }

# Convert path to native format to_native_path() { local path="${1:?Path required}"
case "$(detect_os)" in windows) # Convert /c/Users to C:\Users echo "$path" | sed -e 's|^/\([a-z]\)/|\1:\\|' -e 's|/|\\|g' ;; *) # Unix paths stay as-is echo "$path" ;; esac }
# Convert path to Unix format to_unix_path() { local path="${1:?Path required}"
case "$(detect_os)" in windows) # Convert C:\Users to /c/Users echo "$path" | sed -e 's|\\|/|g' -e 's|^\([A-Za-z]\):|/\L\1|' ;; *) echo "$path" ;; esac }
# Get home directory reliably get_home() { if [[ -n "${HOME:-}" ]]; then echo "$HOME" elif [[ -n "${USERPROFILE:-}" ]]; then to_unix_path "$USERPROFILE" else getent passwd "$(id -un)" | cut -d: -f6 fi }

# Safely source a file if it exists and is readable # Arguments: # $1 - File path safe_source() { local file="${1:?File path required}"
if [[ -f "$file" ]] && [[ -r "$file" ]]; then # shellcheck source=/dev/null source "$file" return 0 fi return 1 }
# Source all files in a directory source_directory() { local dir="${1:?Directory required}" local pattern="${2:-*.sh}"
if [[ ! -d "$dir" ]]; then return 0 fi
local file for file in "$dir"/$pattern; do [[ -f "$file" ]] && safe_source "$file" done }

#!/usr/bin/env bash set -euo pipefail
# Global array to track cleanup tasks declare -a CLEANUP_TASKS=()
# Add a cleanup task add_cleanup() { CLEANUP_TASKS+=("$*") }
# Execute all cleanup tasks run_cleanup() { local exit_code=$? set +e # Don't exit on cleanup errors
for ((i=${#CLEANUP_TASKS[@]}-1; i>=0; i--)); do log_debug "Cleanup: ${CLEANUP_TASKS[i]}" eval "${CLEANUP_TASKS[i]}" || true done
exit "$exit_code" }
# Set up trap for all exit scenarios trap run_cleanup EXIT INT TERM
# Usage example: # temp_dir=$(mktemp -d) # add_cleanup "rm -rf '$temp_dir'" # temp_file=$(mktemp) # add_cleanup "rm -f '$temp_file'"
